DATA = {k: np.array([[float(x) for x in row.split()] for row in v.replace("\n", " ").split(";")]) for k, v in _raw.items()}
NSAT = {"NaX": 6.0, "Na-ZSM-5": 2.0, "H-ZSM-5": 2.0}      # mmol/g, approximate saturation capacities used for the window n <= 0.3 Ns
# gas-specific capacities where the isotherm itself shows saturation well below the generic value:
# SF6/NaX about 2.3 (Table 9), C2H6/NaX about 3.3 (Table 6), SF6 in MFI about 1.7 mmol/g (Tables 15 and 22)
NSAT_GAS = {("SF6", "NaX"): 2.3, ("C2H6", "NaX"): 3.3, ("SF6", "Na-ZSM-5"): 1.7, ("SF6", "H-ZSM-5"): 1.7}
def nsat(gas, solid): return NSAT_GAS.get((gas, solid), NSAT[solid])
if __name__ == "__main__":
    for k, d in DATA.items(): print(k, d.shape, "P", d[0, 0], "-", d[-1, 0], "n", d[0, 1], "-", d[-1, 1])
